    key: "customer_research",
    name: "Customer research",
    description: "Reads what customers and people like them have said, in the project's records and in public, and turns it into findings with sources.",
    category: "product",
    attribute: { name: "Customer research", group: "craft" },
    whenToUse: "Use when asked what customers want, why they buy or leave, what words they use, or who the project is really for, from notes, reviews or public posts.",
    roles: ["product_researcher","product_lead","researcher"],
    defaultFor: ["product_researcher"],
    defaultSince: 1,
    stages: ["drafting","awaiting_signoff","building","selling"],
