    key: "make_media_files",
    name: "Making images and clips for posts",
    description: "Makes a post graphic with Inkscape or GIMP and cuts, converts or extracts media with FFmpeg, all as files for the founder to approve.",
    category: "marketing",
    attribute: { name: "Post media", group: "craft" },
    whenToUse: "Use when a post, page or update needs a picture, a trimmed clip, an audio file or a video poster frame, and you hold the Inkscape, GIMP or FFmpeg tools.",
    roles: ["channel_content","channel_social"],
